    template <typename DestinationElementType, typename SourceElementType, typename SizeType>
    inline void RelocateConstructItems(void* Dest, const SourceElementType* Source, SizeType Count)
    {
        if constexpr (std::is_trivially_copyable_v<SourceElementType> && std::is_same_v<DestinationElementType, SourceElementType>)
        {
            std::memmove(Dest, Source, sizeof(SourceElementType) * Count);
        }
        else
        {
            auto* TypedDest = static_cast<DestinationElementType*>(Dest);

            while (Count > 0)
            {
                ::new (static_cast<void*>(TypedDest)) DestinationElementType(*Source);

                ++TypedDest;

                Source->~SourceElementType();

                ++Source;
                --Count;
            }
        }
    }

